const screen=document.querySelector('#screen');const crumb=document.querySelector('#crumb');const primary=document.querySelector('#primary');
const shots=[['01','와이드 샷','상점 내부 전경','../public/fixtures/shot-wide.jpg'],['02','미디엄 샷','Mina가 뒤를 돌아본다.','../public/fixtures/shot-medium.jpg'],['03','인서트 샷','카세트 플레이어','../public/fixtures/shot-insert.jpg'],['04','클로즈업 샷','Mina의 얼굴','../public/fixtures/shot-closeup.jpg']];
function shot(){crumb.textContent='The Last Cassette › 장면 03 › 오래된 상점 › 샷 02';primary.textContent='이 샷 생성 →';screen.innerHTML=`<div class="shot-layout"><aside class="browser"><small>장면 03</small><h2>오래된 상점</h2><p class="muted">Mina가 오래된 상점에 들어가 카세트 플레이어를 발견한다.</p><input placeholder="샷 검색..." style="width:100%;margin:10px 0 12px"><div class="shots">${shots.map((s,i)=>`<div class="shot ${i===1?'active':''}"><img src="${s[3]}"><div><small>${s[0]}</small><b style="display:block">${s[1]}</b><small class="muted">${s[2]}</small></div></div>`).join('')}</div></aside><section class="canvas"><div class="head"><div><h1>샷 02&nbsp;&nbsp;미디엄 샷</h1><p class="muted">Mina가 소리를 듣고 천천히 뒤를 돌아본다.</p></div><button class="control">첫 프레임(참조)⌄</button></div><div class="preview"><img src="../public/fixtures/mina-old-shop-main.jpg"></div><div class="strip">${Array.from({length:7},()=>`<img src="../public/fixtures/shot-medium.jpg">`).join('')}</div></section><aside class="inspect"><h2>연출 설정</h2><section><h3>연기</h3><p class="muted">캐릭터의 행동과 감정을 설정합니다.</p><label>행동<textarea>소리를 듣고 천천히 뒤를 돌아본다.</textarea></label><div class="grid2"><label>표정<select><option>불안한</option></select></label><label>시선<select><option>왼쪽</option></select></label></div></section><section><h3>카메라</h3><p class="muted">카메라의 구도와 움직임을 설정합니다.</p><div class="segments"><button>클로즈업</button><button class="active">미디엄 샷</button><button>와이드 샷</button><button>기타</button></div><label>카메라 움직임<select><option>느린 돌리 인 (Slow Dolly In)</option></select></label><label>앵글<select><option>눈높이</option></select></label></section><section><h3>조명과 환경</h3><div class="grid2"><label>기본 조명<select><option>텅스텐 (실내)</option></select></label><label>시간대<select><option>밤</option></select></label></div></section></aside></div>`}
function project(){crumb.textContent='The Last Cassette › 프로젝트';primary.textContent='캐릭터 확인 →';screen.innerHTML=`<div class="simple"><div class="hero"><small>프로젝트</small><h1>무엇을 만들고 싶으신가요?</h1><p class="muted">아이디어를 입력하면 캐릭터, 장소, 장면과 비주얼 방향을 준비합니다.</p><textarea style="width:100%;min-height:130px">비 오는 서울에서 한 여성이 오래된 카세트 플레이어를 발견한다. 그리고 그 카세트는 잊었던 기억을 다시 불러온다.</textarea></div><div class="cards"><div class="card"><b>캐릭터</b><p>Mina · 32세</p></div><div class="card"><b>장소</b><p>비 오는 골목 · 오래된 상점 · 아파트</p></div><div class="card"><b>장면</b><p>4개 장면 자동 구성</p></div></div></div>`}
function character(){crumb.textContent='The Last Cassette › 캐릭터 › Mina';primary.textContent='캐릭터 확정 →';screen.innerHTML=`<div class="character-grid"><div><small>캐릭터</small><h2>Mina</h2><div class="card"><img src="../public/fixtures/mina-portrait.jpg" style="width:100%;border-radius:8px"><b>Mina</b><p class="muted">32세 · 한국인 여성</p></div></div><div><h1>캐릭터 시트</h1><div class="preview"><img src="../public/fixtures/mina-old-shop-main.jpg"></div><div class="strip">${['mina-portrait.jpg','shot-medium.jpg','shot-closeup.jpg','shot-wide.jpg'].map(x=>`<img src="../public/fixtures/${x}">`).join('')}</div></div><div><h2>기준 모습</h2><label>머리<input value="짧은 검은 보브컷 🔒"></label><label>눈<input value="갈색 🔒"></label><label>고유 특징<input value="왼쪽 눈 아래 작은 점 🔒"></label><h3>상태</h3><p>젖음 · 피곤함 · 부상</p></div></div>`}
function scene(){crumb.textContent='The Last Cassette › 장면 03 › 오래된 상점';primary.textContent='샷 구성 →';screen.innerHTML=`<div class="simple"><small>장면 03</small><h1>오래된 상점</h1><p class="muted">Mina가 오래된 상점에 들어가 카세트 플레이어를 발견한다.</p><div class="cards"><div class="card"><b>캐릭터</b><p>Mina</p><small>젖음 · 피곤함</small></div><div class="card"><b>장소</b><p>오래된 상점</p><small>밤 · 강한 비</small></div><div class="card"><b>소품</b><p>카세트 플레이어</p><small>은색 메탈 · 검은 버튼</small></div></div><div class="preview" style="margin-top:18px"><img src="../public/fixtures/mina-old-shop-main.jpg"></div></div>`}
function generate(){crumb.textContent='The Last Cassette › 생성';primary.textContent='이 버전 사용';screen.innerHTML=`<div class="simple"><small>생성 결과</small><h1>샷 02 · 미디엄 샷</h1><p class="muted">버전 1 · 8초 · 완료</p><div class="preview"><img src="../public/fixtures/mina-old-shop-main.jpg"></div><div class="cards" style="margin-top:16px"><div class="card"><b>V1</b><p>선택됨</p></div><div class="card"><b>다시 생성</b><p>같은 연출로 새 결과</p></div><div class="card"><b>샷 수정</b><p>기존 설정을 유지하고 돌아가기</p></div></div></div>`}
const render={project,character,scene,shot,generate};document.querySelectorAll('[data-screen]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-screen]').forEach(x=>x.classList.remove('active'));b.classList.add('active');render[b.dataset.screen]()}));primary.addEventListener('click',()=>{if(primary.textContent.includes('생성')){document.querySelector('[data-screen="generate"]').click()}});shot();
